import { useGLTF } from '@react-three/drei';
import type * as THREE from 'three';
import glbUrl from '@/assets/theodolite.glb';

/**
 * Named nodes present in src/assets/theodolite.glb (generated by
 * scripts/generate-glb.mjs). Names match the C4D export so the model
 * can be swapped without touching React.
 */
export interface TheodoliteNodes {
  Base: THREE.Mesh;
  Alidada: THREE.Mesh;
  Telescope: THREE.Mesh;
}

export function useTheodoliteGLB() {
  const gltf = useGLTF(glbUrl);
  return { nodes: gltf.nodes as unknown as TheodoliteNodes };
}

useTheodoliteGLB.preload = () => useGLTF.preload(glbUrl);
